#include <libmtp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(int argc,char **argv){LIBMTP_Init();LIBMTP_raw_device_t*r=NULL;int n=0;if(LIBMTP_Detect_Raw_Devices(&r,&n)||!n)return 1;LIBMTP_mtpdevice_t*d=NULL;for(int i=0;i<n;i++)if(r[i].device_entry.vendor_id==0x057e&&r[i].device_entry.product_id==0x201d)d=LIBMTP_Open_Raw_Device_Uncached(&r[i]);free(r);if(!d)return 2;LIBMTP_Get_Storage(d,0);uint32_t sid=0;for(LIBMTP_devicestorage_t*s=d->storage;s;s=s->next){printf("STORAGE %u %s\n",s->id,s->StorageDescription);if(!strcmp(s->StorageDescription,getenv("MTP_STORAGE")?getenv("MTP_STORAGE"):"1: SD Card"))sid=s->id;}if(!sid){LIBMTP_Release_Device(d);return 3;}uint32_t parent=0xffffffff;if(argc>1){char *part=strtok(argv[1],"/");while(part){LIBMTP_file_t*f=LIBMTP_Get_Files_And_Folders(d,sid,parent);uint32_t found=0;while(f){LIBMTP_file_t*next=f->next;if(!strcmp(f->filename,part))found=f->item_id;LIBMTP_destroy_file_t(f);f=next;}if(!found){printf("NOT FOUND %s\n",part);LIBMTP_Release_Device(d);return 4;}parent=found;part=strtok(NULL,"/");}}if(argc>2){unsigned char* data=NULL;uint32_t got=0;int res=LIBMTP_GetPartialObject(d,parent,0,65536,&data,&got);if(!res){FILE*out=fopen(argv[2],"wb");if(out){fwrite(data,1,got,out);fclose(out);}else res=-1;}free(data);printf("DOWNLOAD status %d bytes %u\n",res,got);if(res)LIBMTP_Dump_Errorstack(d);}else{LIBMTP_file_t*f=LIBMTP_Get_Files_And_Folders(d,sid,parent);while(f){LIBMTP_file_t*next=f->next;printf("%u %llu %s\n",f->item_id,(unsigned long long)f->filesize,f->filename);LIBMTP_destroy_file_t(f);f=next;}}LIBMTP_Release_Device(d);return 0;}
